def areEquivalent(num1,num2):
    def divSum(n):
        sum_div = 1
        i = 2
        while(i * i <= n):
            if (n % i == 0):
                sum_div = (sum_div + i + math.floor(n / i))
            i += 1
        return sum_div
    return divSum(num1) == divSum(num2)

