    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(i + 1):

            if j == 0:
                dp[i][j] = dp[i-1][j]
            else:
                dp[i][j] = dp[i-1][j] + dp[i-1][j-1]

    ans = 0
    for j in range(n + 1):
        ans += dp[n][j] * dp[n][j]

