    for i in range(1, n + 1):
        for j in range(i + 1):
            dp[i][j] = dp[i - 1][j]
            if j > 0:
                dp[i][j] += dp[i - 1][j - 1]

    ans = 0
    for s in range(n + 1):
        ans += dp[n][s] * dp[n][s]
