def count_binary_seq(n):
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Base case: For length 0, sum 0, there's 1 way (empty sequence)
    dp[0][0] = 1

    # Fill the DP table
    for length in range(1, n + 1):
        for current_sum in range(length + 1):
            # Option 1: Append a '0'
            if current_sum <= length - 1:
                dp[length][current_sum] += dp[length - 1][current_sum]
            # Option 2: Append a '1'
            if current_sum >= 1 and current_sum - 1 <= length - 1:
                dp[length][current_sum] += dp[length - 1][current_sum - 1]

    ans = 0
    # Sum up the squares of counts for each possible sum
    for s in range(n + 1):
        ans += dp[n][s] * dp[n][s]
    return ans

