def get_max_sum(n, memo={}):
    if n == 0:
        return 0
    if n in memo:
        return memo[n]

    max_sum = max( (get_max_sum(n // 2, memo) + get_max_sum(n // 3, memo) + get_max_sum(n // 4, memo) + get_max_sum(n // 5, memo)), n)
    memo[n] = max_sum
    return max_sum

def count_bidirectional(pairs):
    count = 0
    seen = set()
    for a, b in pairs:
        if (a, b) in seen:
            continue
        if (b, a) in seen:
            count += 1
            seen.add((a, b)) 
        else:
            seen.add((a, b))
    return count

def even_binomial_Coeff_Sum(n):
