def find_ways(length, values):
    dp = {}
    dp[(0, 0)] = 1
    for i in range(1, length + 1):
        for j in range(length * max(abs(v) for v in values) + 1):
            dp[(i, j)] = 0
            for v in values:
                prev_sum = j - v
                if prev_sum >= 0 and (i - 1, prev_sum) in dp:
                    dp[(i, j)] += dp[(i - 1, prev_sum)]
    count = 0
    for j in range(length * max(abs(v) for v in values) + 1):
        count += dp.get((length, j), 0)
    return count

def find_ways(N, K):
    dp = [[0] * (K + 1) for _ in range(N + 1)]

    # Base case: For length 0, there's one way (empty sequence) with prefix sum 0.
    dp[0][0] = 1

    for i in range(1, N + 1):
        for j in range(K + 1):
            # Option 1: Add +1
            if j - 1 >= 0:
                dp[i][j] += dp[i - 1][j - 1]
            # Option 2: Add -1
            if j + 1 <= K:
                dp[i][j] += dp[i - 1][j + 1]
    return dp[N][0]

