        for j in range(k + 1):
            for x in arr:
                if j - x >= 0:
                    dp[i][j] += dp[i - 1][j - x]
                    dp[i][j] %= m

    return sum(dp[n]) % m

def find_ways(n, x, y):
    dp = {}

    def solve(length, current_sum):
        if length == 0:
            return 1 if current_sum >= 0 else 0
        if (length, current_sum) in dp:
            return dp[(length, current_sum)]

        count = 0
        # Try adding x
        if current_sum + x >= 0:
            count += solve(length - 1, current_sum + x)
        # Try adding y
        if current_sum + y >= 0:
            count += solve(length - 1, current_sum + y)

        dp[(length, current_sum)] = count
        return count

    return solve(n, 0)

