    for i in range(1, n + 1):
        for j in range(2 * n + 1):
            if j - vals[i - 1] >= 0 and j - vals[i - 1] <= 2 * n:
                dp[i][j] += dp[i - 1][j - vals[i - 1]]
            if j + vals[i - 1] >= 0 and j + vals[i - 1] <= 2 * n:
                dp[i][j] += dp[i - 1][j + vals[i - 1]]
