def find_ways(n, s, vals):
    dp = [[0] * (2 * s + 1) for _ in range(n + 1)]
    dp[0][s] = 1

    for i in range(1, n + 1):
        for j in range(2 * s + 1):
            for val in vals:
                prev_sum_idx = j - val
                if 0 <= prev_sum_idx <= 2 * s:
                    if prev_sum_idx <= s:  # Ensure prefix sum is non-negative
                        dp[i][j] += dp[i - 1][prev_sum_idx]

    total_ways = 0
    for j in range(s, 2 * s + 1):
        total_ways += dp[n][j]
    return total_ways

def find_ways(values, length):
    memo = {}

    def solve(idx, current_sum, remaining_length):
        if remaining_length == 0:
            return 1 if current_sum >= 0 else 0
        if (idx, current_sum, remaining_length) in memo:
            return memo[(idx, current_sum, remaining_length)]

        count = 0
        for val in values:
            if current_sum + val >= 0:
                count += solve(idx + 1, current_sum + val, remaining_length - 1)

        memo[(idx, current_sum, remaining_length)] = count
        return count

    return solve(0, 0, length)

def sum_difference(n):
    sum_of_squares = 0
    for i in range(1, n + 1):
        sum_of_squares += i * i

    square_of_sum = 0
    for i in range(1, n + 1):
        square_of_sum += i
    square_of_sum = square_of_sum * square_of_sum

    return square_of_sum - sum_of_squares

