def add_nested_tuples(tuple1, tuple2):
    result = []
    for i in range(len(tuple1)):
        inner_tuple = []
        for j in range(len(tuple1[i])):
            inner_tuple.append(tuple1[i][j] + tuple2[i][j])
        result.append(tuple(inner_tuple))
    return tuple(result)

