def newman_prime(n: int):

    if n == 0:
        return 2

    # Initialize a list to store Newman-Shanks-Williams numbers
    nsw_numbers = [0] * (n + 1)
    nsw_numbers[0] = 1
    nsw_numbers[1] = 1

    # Calculate NSW numbers up to n
    for i in range(2, n + 1):
        nsw_numbers[i] = 2 * nsw_numbers[i - 1] + nsw_numbers[i - 2]

    # Check for primality using trial division
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    # Find the nth prime NSW number
    count = -1
    for i in range(n + 1):
        if is_prime(nsw_numbers[i]):
            count += 1
            if count == n:
                return nsw_numbers[i]

