def magic_square_test(my_matrix):
    n = len(my_matrix)
    if n == 0:
        return True

    # Calculate the sum of the first row to compare with others
    target_sum = sum(my_matrix[0])

    # Check rows
    for row in my_matrix:
        if sum(row) != target_sum:
            return False

    # Check columns
    for col_idx in range(n):
        current_col_sum = 0
        for row_idx in range(n):
            current_col_sum += my_matrix[row_idx][col_idx]
        if current_col_sum != target_sum:
            return False

    # Check main diagonal
    main_diag_sum = 0
    for i in range(n):
        main_diag_sum += my_matrix[i][i]
    if main_diag_sum != target_sum:
        return False

    # Check anti-diagonal
    anti_diag_sum = 0
    for i in range(n):
        anti_diag_sum += my_matrix[i][n - 1 - i]
    if anti_diag_sum != target_sum:
        return False

    return True

