import heapq
from collections import Counter
def rearange_string(S):
    ctr = Counter(S)
    heap = [(-value, key) for key, value in ctr.items()]
    heapq.heapify(heap)
    if not heap:
        return ""
    if (-heap[0][0]) * 2 > len(S) + 1: 
        return ""

    ans = [None] * len(S)

    i = 0
    while heap:
        nct, char = heapq.heappop(heap)
        for _ in range(-nct):
            if i >= len(S):
                i = 1 
            ans[i] = char
            i += 2

    return "".join(ans)

