def is_Sum_Of_Powers_Of_Two(n):
    if n <= 0:
        return False
    while n > 0:
        if n % 2 == 0:
            return False
        n //= 2
    return True

def is_Sum_Of_Powers_Of_Two(n):
    if n <= 0:
        return False

    while n > 0:
        if n & 1:  # Check if the last bit is 1
            n >>= 1  # Right shift to check the next bit
            if n > 0 and n & 1 == 0:  # If there's a 0 after a 1, it's not a power of 2
                return False
        else:
            n >>= 1  # Right shift to check the next bit

    return True

