def convert_list_dictionary(list_of_lists):
    if not list_of_lists:
        return []

    # Get the keys from the first list
    keys = list_of_lists[0]

    # Initialize a list to store the dictionaries
    result = []

    # Iterate through the rest of the lists (values)
    for i in range(1, len(list_of_lists)):
        values = list_of_lists[i]

        # Create a dictionary for the current row of values
        row_dict = {}
        for j in range(len(keys)):
            current_dict = row_dict
            # Nest dictionaries for all but the last key-value pair
            for k in range(len(keys) - j - 1):
                if keys[j + k] not in current_dict:
                    current_dict[keys[j + k]] = {}
                current_dict = current_dict[keys[j + k]]

            # Assign the final value
            if j < len(values): # Ensure there is a corresponding value
                current_dict[keys[len(keys) - 1]] = values[j]
            else: # Handle cases where there are fewer values than keys
                current_dict[keys[len(keys) - 1]] = None # Or some other default

        result.append(row_dict)

    return result

