def find_Max_Len_Even(str):
    n = len(str)
    i = 0
    maxLen = 0
    while i < n:
        if str[i] == ' ':
            i += 1
            continue
        j = i
        while j < n and str[j] != ' ':
            j += 1
        currentLen = j - i
        if currentLen % 2 == 0:
            maxLen = max(maxLen, currentLen)
        i = j
    return maxLen

