def frequency_Of_Smallest(arr):
    mn = arr[0]
    freq = 1
    for i in range(1, len(arr)):
        if (arr[i] < mn):
            mn = arr[i]
            freq = 1
        elif (arr[i] == mn):
            freq += 1
    return freq

