def count_bidirectional(pairs):
    count = 0
    seen = set()
    for a, b in pairs:
        if (a, b) in seen or (b, a) in seen:
            continue
        if (b, a) in pairs:
            count += 1
            seen.add((a, b))
            seen.add((b, a))
    return count

