def find_ways(n):
    if n % 2 != 0:
        return 0

    val = 1
    r = n // 2

    for i in range(0, r):
        val *= (2 * r - i)
        val //= (i + 1)

    catalan = val // (r + 1)
    return catalan

def find_ways(arr, n, length):
    dp = [[0] * (n + 1) for _ in range(length + 1)]

    for i in range(n + 1):
        dp[0][i] = 1

    for l in range(1, length + 1):
        for s in range(n + 1):
            for x in arr:
                if s - x >= 0:
                    dp[l][s] += dp[l - 1][s - x]
    return dp[length][0]

def find_ways(arr, n, length, current_sum=0, index=0):
    if index == length:
        return 1

    count = 0
    for i in range(n):
        if current_sum + arr[i] >= 0:
            count += find_ways(arr, n, length, current_sum + arr[i], index + 1)
    return count

def find_ways(total_sum, length, values):
    dp = [[0] * (total_sum + 1) for _ in range(length + 1)]
    dp[0][0] = 1

    for i in range(1, length + 1):
        for j in range(total_sum + 1):
            for val in values:
                if j >= val:
                    dp[i][j] += dp[i - 1][j - val]
    return dp[length]

def find_ways(n, A):
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(i + 1):
            if j > 0:
                dp[i][j] += dp[i - 1][j - 1] * A[0]
            if j < i:
                dp[i][j] += dp[i - 1][j + 1] * A[1]
    return dp[n][0]

def find_ways(n, k):
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    # Base case: for length 0, there's one way (empty sequence)
    dp[0][0] = 1

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(k + 1):
            # Option 1: Add a +1 (if prefix sum allows)
            if j > 0:
                dp[i][j] += dp[i - 1][j - 1]
            # Option 2: Add a -1 (if prefix sum allows)
            if j < k:
