def find_ways(n, m):
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(n + 1):
            if j - 1 >= 0:
                dp[i][j] += dp[i - 1][j - 1]
            if j + 1 <= n and j + 1 <= m:
                dp[i][j] += dp[i - 1][j + 1]

    return dp[n][0]

def find_ways(arr, k):
    n = len(arr)
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(k + 1):
            if arr[i - 1] >= 0:
                for prev_sum in range(k + 1 - arr[i - 1]):
                    dp[i][j] += dp[i - 1][prev_sum]
            else:  # arr[i-1] < 0
                for prev_sum in range(-arr[i - 1], k + 1):
                    dp[i][j] += dp[i - 1][prev_sum]
    return dp[n][k]

def find_ways(arr, k):
    """
    Counts the number of sequences of length k that can be formed using elements from arr,
    such that all prefix sums of the sequence are non-negative.
    """
    n = len(arr)
    dp = {}

    def solve(index, current_sum, length):
        if length == k:
            return 1 if current_sum >= 0 else 0
        if (index, current_sum, length) in dp:
            return dp[(index, current_sum, length)]

        count = 0
        for i in range(n):
            new_sum = current_sum + arr[i]
            if new_sum >= 0:
                count += solve(i, new_sum, length + 1)
        dp[(index, current_sum, length)] = count
        return count

    total_ways = 0
    for i in range(n):
        if arr[i] >= 0:
            total_ways += solve(i, arr[i], 1)
    return total_ways

def find_ways(values, length):
    memo = {}

    def solve(k, current_sum):
        if (k, current_sum) in memo:
            return memo[(k, current_sum)]

        if k == 0:
            return 1 if current_sum >= 0 else 0

        count = 0
        for val in values:
            if current_sum + val >= 0:
                count += solve(k - 1, current_sum + val)

        memo[(k, current_sum)] = count
        return count

    return solve(length, 0)

def find_ways(values, length):
    """
    This function counts sequences of given length having non-negative prefix sums that can be generated by given values.

    Args:
        values (list): A list of integers representing the available values.
        length (int): The desired length of the sequences.

    Returns:
        int: The number of valid sequences.
    """
    if length == 0:
        return 1

    count = 0
    dp = {0: 1}  # dp[prefix_sum] = number of ways to achieve this prefix_sum

    for _ in range(length):
        new_dp = {}
        for current_sum, ways in dp.items():
            for val in values:
                next_sum = current_sum + val
                if next_sum >= 0:
                    new_dp[next_sum] = new_dp.get(next_sum, 0) + ways
        dp = new_dp

    return sum(dp.values())

