def extract_symmetric(tuple_list):
    symmetric_pairs = []
    seen_pairs = set()

    for pair in tuple_list:
        a, b = pair
        if (b, a) in seen_pairs:
            symmetric_pairs.append(pair)
            symmetric_pairs.append((b, a))
        seen_pairs.add(pair)
    return symmetric_pairs

