def comb_sort(input_list):
    n = len(input_list)
    gap = n
    shrink = 1.3
    sorted_flag = False

    while gap > 1 or not sorted_flag:
        gap = int(gap / shrink)
        if gap < 1:
            gap = 1
        sorted_flag = True
        for i in range(n - gap):
            if input_list[i] > input_list[i + gap]:
                input_list[i], input_list[i + gap] = input_list[i + gap], input_list[i]
                sorted_flag = False
    return input_list

