    n = len(arr)
    if n == 0:
        return 0

    # Kadane's algorithm for a single array
    def kadane(current_arr):
        max_so_far = -float('inf')
        current_max = 0
        for x in current_arr:
            current_max += x
            if current_max > max_so_far:
                max_so_far = current_max
            if current_max < 0:
                current_max = 0
        return max_so_far

    # Case 1: k = 1 (single array)
    if k == 1:
        return kadane(arr)

    # Case 2: k > 1

    # Sum of the original array
    arr_sum = sum(arr)

    # Max subarray sum for a single array (used for any internal segment)
    max_subarray_single = kadane(arr)

    # Max subarray sum for two concatenated arrays (arr + arr)
    # This helps determine if the sum of the full array is beneficial or not
    max_subarray_double = kadane(arr + arr)

    if arr_sum > 0:
        # If the sum of the array is positive, repeating it k-2 times will add (k-2) * arr_sum
        return max(max_subarray_single, max_subarray_double + (k - 2) * arr_sum)
    else:
        # If the sum of the array is negative or zero, repeating it more than twice will likely decrease the sum
        # So, the maximum sum will be either from a single array or two concatenated arrays.
        return max(max_subarray_single, max_subarray_double)

