                max_so_far = current_max
        return max_so_far if max_so_far != -float('inf') else 0

    # Case for k > 1
    # Concatenate the array twice to handle cases where the max sum spans across the boundary
    # For example, in [-2, 1, -3, 4, -1, 2, 1, -5, 4], max subarray sum is 6 from [4, -1, 2, 1].
    # If k=2, and arr = [1, 2, -5, 4, 1], then repeated array is [1, 2, -5, 4, 1, 1, 2, -5, 4, 1].
    # The max sum can be from [4, 1, 1, 2] = 8.
    extended_arr = arr + arr
    max_sum_extended = -float('inf')
    current_sum_extended = 0

    for x in extended_arr:
        current_sum_extended += x
        if current_sum_extended < x:
            current_sum_extended = x
        if max_sum_extended < current_sum_extended:
            max_sum_extended = current_sum_extended

    total_array_sum = sum(arr)

    if total_array_sum > 0:
        return max_sum_extended + (k - 2) * total_array_sum
    else:
        return max_sum_extended if max_sum_extended != -float('inf') else 0

def max_sub_array_sum_repeated(arr, k):
    n = len(arr)
    if n == 0:
        return 0

    max_so_far = float('-inf')
    current_max = 0
    total_sum_single = 0

    # Calculate max subarray sum for a single array and total sum of a single array
    for x in arr:
        current_max += x
        if current_max < x:
            current_max = x
        if current_max > max_so_far:
            max_so_far = current_max
        total_sum_single += x

    if k == 1:
        return max_so_far

    # If all numbers are negative, the max subarray sum is the largest single element
    if all(x < 0 for x in arr):
        return max(arr)

    # Calculate max subarray sum for two concatenated arrays
    # This covers cases where the max subarray spans across the boundary
    # e.g., a suffix of the first array + a prefix of the second array
    current_max_double = 0
    max_so_far_double = float('-inf')
    extended_arr = arr + arr
    for x in extended_arr:
        current_max_double += x
        if current_max_double < x:
            current_max_double = x
        if current_max_double > max_so_far_double:
            max_so_far_double = current_max_double

    # If the total sum of a single array is negative or zero,
    # repeating it more times won't increase the sum beyond what's found in two arrays.
    if total_sum_single <= 0:
        return max_so_far_double
    else:
        # If total sum of single array is positive,
        # we can add (k-2) * total_sum_single to the max sum found in two arrays.
        # This is because the middle (k-2) arrays will contribute their full sum.
        return max(max_so_far, max_so_far_double, total_sum_single * (k - 2) + max_so_far_double)

def max_sub_array_sum_repeated(arr, k):
    n = len(arr)
    if n == 0:
        return 0

    max_so_far = -float('inf')
    current_max = 0
    total_sum = sum(arr)

    if k == 1:
        for x in arr:
            current_max += x
            if current_max > max_so_far:
                max_so_far = current_max
            if current_max < 0:
                current_max = 0
        return max_so_far if max_so_far != -float('inf') else max(arr)

    # Kadane's algorithm for two concatenations
    temp_arr = arr + arr
    max_so_far_double = -float('inf')
    current_max_double = 0
    for x in temp_arr:
        current_max_double += x
        if current_max_double > max_so_far_double:
            max_so_far_double = current_max_double
        if current_max_double < 0:
            current_max_double = 0

    if k == 2:
        return max_so_far_double if max_so_far_double != -float('inf') else max(temp_arr)

    # For k > 2, the pattern emerges
    # The max sum will be either the max sum of a single or double array,
    # or the sum of the whole array multiplied by (k-2) plus the max sum of the double array.

    if total_sum > 0:
        return max_so_far_double + (k - 2) * total_sum
    else:
        return max_so_far_double

