def max_profit(prices, k):
    n = len(prices)

    if n == 0 or k == 0:
        return 0

    if k >= n // 2:  # If k is large enough, it's equivalent to unlimited transactions
        max_profit_val = 0
        for i in range(1, n):
            if prices[i] > prices[i - 1]:
                max_profit_val += prices[i] - prices[i - 1]
        return max_profit_val

    dp = [[0] * n for _ in range(k + 1)]

    for i in range(1, k + 1):
        max_diff = -prices[0]
        for j in range(1, n):
            dp[i][j] = max(dp[i][j - 1], prices[j] + max_diff)
            max_diff = max(max_diff, dp[i - 1][j] - prices[j])

    return dp[k][n - 1]

