def max_profit(prices, k):
    n = len(prices)
    if n == 0 or k == 0:
        return 0

    dp = [[[0] * 2 for _ in range(k + 1)] for _ in range(n)]

    for t in range(k + 1):
        dp[0][t][0] = 0
        dp[0][t][1] = -prices[0]

    for i in range(1, n):
        for t in range(1, k + 1):
            dp[i][t][0] = max(dp[i - 1][t][0], dp[i - 1][t][1] + prices[i])
            dp[i][t][1] = max(dp[i - 1][t][1], dp[i - 1][t - 1][0] - prices[i])

    return dp[n - 1][k][0]

