def division_elements(tup1, tup2):
    """
    Performs mathematical division operation across the given tuples.

    Args:
        tup1 (tuple): The dividend tuple.
        tup2 (tuple): The divisor tuple.

    Returns:
        tuple: A new tuple containing the results of the division.
               Returns an empty tuple if the input tuples have different lengths,
               or if a ZeroDivisionError occurs.
    """
    if len(tup1) != len(tup2):
        return ()

    result = []
    for i in range(len(tup1)):
        try:
            result.append(tup1[i] / tup2[i])
        except ZeroDivisionError:
            return ()
        except TypeError:
            # Handle cases where elements might not be numbers
            return ()
    return tuple(result)

def division_elements(tup1, tup2):
    """
    Performs element-wise division of two tuples.

    Args:
        tup1: The first tuple (dividend).
        tup2: The second tuple (divisor).

    Returns:
        A new tuple containing the results of the division.
        If the tuples have different lengths, it returns an empty tuple.
        If division by zero occurs, it returns an empty tuple.
    """
    if len(tup1) != len(tup2):
        return ()

    result = []
    for i in range(len(tup1)):
        if tup2[i] == 0:
            return ()
        result.append(tup1[i] / tup2[i])
    return tuple(result)

