import collections


def is_tree_balanced(tree):
    if tree is None:
        return True

    queue = collections.deque([(tree, 0)])
    nodes_at_depth = {}

    while queue:
        node, depth = queue.popleft()

        if depth not in nodes_at_depth:
            nodes_at_depth[depth] = 0
        nodes_at_depth[depth] += 1

        if node.left:
            queue.append((node.left, depth + 1))
        if node.right:
            queue.append((node.right, depth + 1))

    min_depth = min(nodes_at_depth.keys())
    max_depth = max(nodes_at_depth.keys())

    return max_depth - min_depth <= 1

