def is_tree_balanced(tree):


    if tree is None:
        return True


    q = collections.deque()
    q.append((tree, 0)) # (node, level)


    levels = []
    while q:
        node, level = q.popleft()


        if node.left:
            q.append((node.left, level + 1))
        if node.right:
            q.append((node.right, level + 1))


        levels.append(level)


    max_level = max(levels)
    min_level = min(levels)


    if max_level - min_level > 1:
        return False
    else:
        return True

