import math

def get_Min_Squares(n):
    if n < 0:
        return 0
    if n == 0:
        return 0
    if n == 1:
        return 1

    dp = [0] * (n + 1)
    dp[0] = 0
    dp[1] = 1

    for i in range(2, n + 1):
        dp[i] = float('inf')
        for j in range(1, int(math.sqrt(i)) + 1):
            dp[i] = min(dp[i], 1 + dp[i - j * j])
    return dp[n]

import math
def get_Min_Squares(n):
    if n < 0:
        return 0
    if n == 0:
        return 0
    if n == 1:
        return 1

    dp = [0] * (n + 1)
    dp[0] = 0
    dp[1] = 1

    for i in range(2, n + 1):
        min_val = float('inf')
        j = 1
        while j * j <= i:
            min_val = min(min_val, dp[i - j * j])
            j += 1
        dp[i] = min_val + 1
    return dp[n]

