    divisor_counts = {}
    for num in range(a, b + 1):
        for divisor in range(1, num + 1):
            if num % divisor == 0:
                divisor_counts[divisor] = divisor_counts.get(divisor, 0) + 1

    if not divisor_counts:
        return 1 if a <= 1 <= b else -1 # No numbers in range, or range is empty and 1 is not in it. Default to 1 if 1 is a possible divisor

