        l, R = r[0], r[1]

        # If the index is within the rotation range
        if l <= index <= R:
            # Calculate the new index after rotation
            # The element at index 'i' in the original range [l,R] moves to 'l + (i - l - 1 + R - l + 1) % (R - l + 1)'
            # which simplifies to 'l + (i - l - 1 + length) % length'
            # or in simpler terms, the element at 'index' moves to 'index - 1' unless 'index' is 'l', in which case it moves to 'R'

            if index == l:
                index = R
            else:
                index -= 1
    return arr[index]

