        left = ranges[i][0]
        right = ranges[i][1]

        if left <= index <= right:
            if index == left:
                index = right
            else:
                index -= 1
    return arr[index]

def find_Element(arr, ranges, rotations, index):
    for i in range(rotations):
        left = ranges[i][0]
        right = ranges[i][1]
        if left <= index <= right:
            index = left + (right - index)
    return arr[index]

def find_Element(arr, n, k, index):
    k %= n
    if index < k:
        return arr[n - k + index]
    else:
        return arr[index - k]

