def max_sum_increasing_subseq(arr, k):
    n = len(arr)
    dp = [0] * n

    # Initialize dp array with the elements themselves
    for i in range(n):
        dp[i] = arr[i]

    # Calculate the maximum sum of increasing subsequence ending at each index
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and dp[i] < dp[j] + arr[i]:
                dp[i] = dp[j] + arr[i]

    # Find the maximum sum of increasing subsequence from prefix till ith index 
    # and also including a given kth element which is after i, i.e., k > i
    max_sum = 0
    for i in range(k):
        if arr[k] > arr[i]:
            max_sum = max(max_sum, dp[i] + arr[k])

    return max_sum

