def find_Nth_Digit(numerator, denominator, n):
    if n <= 0:
        return -1

    remainder = numerator % denominator
    if remainder == 0:
        return 0

    seen_remainders = {}
    decimal_digits = []
    position = 0

    while remainder != 0 and remainder not in seen_remainders:
        seen_remainders[remainder] = position
        remainder *= 10
        decimal_digits.append(remainder // denominator)
        remainder %= denominator
        position += 1

    if n <= len(decimal_digits):
        return decimal_digits[n - 1]
    else:
        if remainder == 0:
            return 0
        else:
            start_of_cycle = seen_remainders[remainder]
            cycle_length = len(decimal_digits) - start_of_cycle
            if cycle_length == 0:
                return 0 # This case should not be reached if remainder is not 0

            index_in_cycle = (n - 1 - start_of_cycle) % cycle_length
            return decimal_digits[start_of_cycle + index_in_cycle]

