    if not list_of_tuples:
        return []

    # Create a dictionary to store the first occurrence index of each first element
    occurrence_map = {}
    for i, (first_element, *_) in enumerate(list_of_tuples):
        if first_element not in occurrence_map:
            occurrence_map[first_element] = i

    # Sort the list based on the occurrence index
    return sorted(list_of_tuples, key=lambda x: occurrence_map[x[0]])

