def find_minimum_range(nums):
    min_range_start = 0
    min_range_end = float('inf')
    max_val = -float('inf')

    k = len(nums)
    pointers = [0] * k

    while True:
        min_val = float('inf')
        min_idx = -1

        for i in range(k):
            if pointers[i] < len(nums[i]):
                if nums[i][pointers[i]] < min_val:
                    min_val = nums[i][pointers[i]]
                    min_idx = i
                if nums[i][pointers[i]] > max_val:
                    max_val = nums[i][pointers[i]]

        if min_idx == -1:
            break

        if max_val - min_val < min_range_end - min_range_start:
            min_range_start = min_val
            min_range_end = max_val

        pointers[min_idx] += 1
        if pointers[min_idx] == len(nums[min_idx]):
            break

    return [min_range_start, min_range_end]

