def find_minimum_range(nums):
    import heapq

    k = len(nums)
    if k == 0:
        return []

    min_heap = []
    max_val = float('-inf')

    for i in range(k):
        if not nums[i]:
            return []
        heapq.heappush(min_heap, (nums[i][0], i, 0))
        max_val = max(max_val, nums[i][0])

    min_range_start = min_heap[0][0]
    min_range_end = max_val

    while True:
        min_val, list_idx, element_idx = heapq.heappop(min_heap)

        if max_val - min_val < min_range_end - min_range_start:
            min_range_start = min_val
            min_range_end = max_val

        if element_idx + 1 < len(nums[list_idx]):
            next_val = nums[list_idx][element_idx + 1]
            heapq.heappush(min_heap, (next_val, list_idx, element_idx + 1))
            max_val = max(max_val, next_val)
        else:
            break

    return [min_range_start, min_range_end]

