def find_minimum_range(nums):
    min_heap = []
    max_val = -float('inf')

    for i, arr in enumerate(nums):
        if not arr:
            return []  # Handle empty input arrays
        heapq.heappush(min_heap, (arr[0], i, 0))
        max_val = max(max_val, arr[0])

    min_range_start = -float('inf')
    min_range_end = float('inf')

    while len(min_heap) == len(nums):
        min_val, arr_idx, element_idx = heapq.heappop(min_heap)

        if max_val - min_val < min_range_end - min_range_start:
            min_range_start = min_val
            min_range_end = max_val

        if element_idx + 1 < len(nums[arr_idx]):
            next_val = nums[arr_idx][element_idx + 1]
            heapq.heappush(min_heap, (next_val, arr_idx, element_idx + 1))
            max_val = max(max_val, next_val)
        else:
            break  # One array is exhausted

    return [min_range_start, min_range_end]

