import heapq

def rearange_string(s):
    counts = Counter(s)
    heap = []
    for char, count in counts.items():
        heapq.heappush(heap, (-count, char))

    result = []
    prev_char = ''

    while heap:
        neg_count, char = heapq.heappop(heap)

        if char == prev_char:
            if not heap:
                return ""

            neg_count2, char2 = heapq.heappop(heap)
            result.append(char2)
            prev_char = char2

            if neg_count2 + 1 < 0:
                heapq.heappush(heap, (neg_count2 + 1, char2))
            heapq.heappush(heap, (neg_count, char))
        else:
            result.append(char)
            prev_char = char
            if neg_count + 1 < 0:
                heapq.heappush(heap, (neg_count + 1, char))

    return "".join(result)

