def heap_queue_smallest(nums, k):
    if not nums or k <= 0:
        return []

    if k >= len(nums):
        return sorted(nums)

    # Max-heap to store the k smallest elements
    # Python's heapq is a min-heap, so we store negative values
    # to simulate a max-heap.
    heap = []
    for num in nums:
        if len(heap) < k:
            heappush(heap, -num)
        else:
            if num < -heap[0]:
                heappop(heap)
                heappush(heap, -num)

    # Convert back to positive values and sort
    result = [-x for x in heap]
    result.sort()
    return result

def heap_queue_smallest(nums, k):
    if not nums or k <= 0:
        return []

    # Python's heapq is a min-heap. To find the smallest k elements,
    # we can use a max-heap of size k.
    # We store the negative of numbers to simulate a max-heap with a min-heap.

    heap = []
    for num in nums:
        if len(heap) < k:
            heappush(heap, -num)  # Push negative to simulate max-heap
        else:
            if -num > heap[0]:  # If current num is smaller than the largest in heap
                heappop(heap)
                heappush(heap, -num)

    # Extract the elements from the heap and negate them back
    result = []
    while heap:
        result.append(-heappop(heap))

    return sorted(result)

